void mainImage(out vec4 fragColor, vec2 fragCoord) {

    float _seed_variation_ = SEED_VARIATION;

    // Initialize random number generator state
    uint rngState = uint(uint(fragCoord.x) * uint(1973) + 
                         uint(fragCoord.y) * uint(9277) + 
                         uint(iFrame) * uint(26699)) | uint(1);

    // Calculate jittered pixel coordinates
    vec2 xy = fragCoord + vec2(RandomFloat01(rngState), RandomFloat01(rngState));

    // Calculate UV coordinates
    vec2 UV=(xy-iResolution.xy/2.0)/iResolution.y;
    UV.y=-UV.y;
    //frame ajusting
    UV.x+=0.80;
    UV.y+=0.65;
    UV*=0.75;

    // Perform path tracing

    vec3 rgb = pathtracing(UV, _seed_variation_).xyz;//pathtracing(UV,rngState);

    // Set fragment color based on mouse input
    if (iMouse.z < 0.1) {
        // Accumulate new sample with previous frame
        fragColor = vec4(texture(iChannel0, fragCoord / iResolution.xy) + vec4(rgb, 1));
    } else {
        // Use only the current sample
        fragColor = vec4(rgb, 1);
    }
}
